s=open(p).read()
s=s.replace('''ClaimStatus status, Long number, String settledDue) {''','''ClaimStatus status, Long number, String settledDue, String openedBy) {''')
s=s.replace('''claim.getSettledDue().toPlainString());''','''claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy());''')
open(p,'w').write(s)
p='java/net/officefloor/hq/app/claim/ClaimService.java'
s=open(p).read()
s=s.replace('''     * Settling fixes the claim's due''','''     * Opening records who opened it; that user cannot settle it (403).
     * Settling fixes the claim's due''')
s=s.replace('''        Long number = next == ClaimStatus.OPEN ?''','''        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
        }
        Long number = next == ClaimStatus.OPEN ?''')
s=s.replace('''        claim.setNumber(next == ClaimStatus.VOID ? null : number);
''','''        claim.setNumber(next == ClaimStatus.VOID ? null : number);
        if (next == ClaimStatus.OPEN) {
            claim.setOpenedBy(user);
        }
''')
open(p,'w').write(s)
p='frontend/src/app/core/claims.ts'
s=open(p).read()
s=s.replace('''  settledDue: string | null;
}''','''  settledDue: string | null;
  /** The user who opened the claim; null while it has not been opened. That user cannot settle it. */
  openedBy: string | null;
}''')
open(p,'w').write(s)
p='frontend/src/app/features/claims/claims.ts'
s=open(p).read()
s=s.replace('''          <span data-testid="claim-status">{{ c.status }}</span>
''','''          <span data-testid="claim-status">{{ c.status }}</span>
          <span data-testid="claim-opened-by">{{ c.openedBy }}</span>
''')
s=s.replace('''    } catch {
      this.rowError.set({ id: claim.id, message: `A ${claim.status} claim cannot be changed that way.` });''','''    } catch (e) {
      const message = e instanceof HttpErrorResponse && e.status === 403
        ? 'The user who opened a claim cannot settle it.'
        : `A ${claim.status} claim cannot be changed that way.`;
      this.rowError.set({ id: claim.id, message });''')
s="import { HttpErrorResponse } from '@angular/common/http';\n"+s
open(p,'w').write(s)
EOF
